import { useState, type FormEvent } from 'react';
import {
  ZONES,
  ZONE_LABELS,
  activeChips,
  withoutChip,
  type ChipKey,
  type SearchCriteria,
} from '../../lib/search';
import styles from './FilterChips.module.css';

/** Las cinco opciones del formulario «+ Filtro», en el orden de la spec §3. */
const FIELD_OPTIONS: ReadonlyArray<{ key: ChipKey; label: string }> = [
  { key: 'partNumber', label: 'Ref' },
  { key: 'brand', label: 'Marca' },
  { key: 'minQuantity', label: 'Qty mín' },
  { key: 'zone', label: 'Zona' },
  { key: 'maxLeadTimeDays', label: 'Lead time máx' },
];

/**
 * Chips de filtro de SRCH-01.
 *
 * Totalmente controlado: no guarda criterios, los recibe y emite los nuevos
 * enteros. El único estado propio es el del formulario en línea («+ Filtro»):
 * si está abierto, qué campo tiene elegido y qué hay tecleado.
 */
export function FilterChips({
  criteria,
  onChange,
}: {
  criteria: SearchCriteria;
  onChange: (next: SearchCriteria) => void;
}) {
  const [open, setOpen] = useState(false);
  const [field, setField] = useState<ChipKey>('partNumber');
  const [value, setValue] = useState('');

  const chips = activeChips(criteria);

  const handleAdd = (e: FormEvent) => {
    e.preventDefault();
    const v = value.trim();
    if (!v) return;

    let next = { ...criteria };
    switch (field) {
      case 'partNumber':
        next = { ...next, partNumber: v };
        break;
      case 'brand':
        next = { ...next, brand: v };
        break;
      case 'minQuantity': {
        const n = Number(v);
        if (!Number.isFinite(n) || n < 0) return;
        next = { ...next, minQuantity: Math.round(n) };
        break;
      }
      case 'maxLeadTimeDays': {
        const n = Number(v);
        if (!Number.isFinite(n) || n < 0) return;
        next = { ...next, maxLeadTimeDays: Math.round(n) };
        break;
      }
      case 'zone': {
        const z = v as (typeof ZONES)[number];
        if (!ZONES.includes(z)) return;
        next = { ...next, zone: z };
        break;
      }
    }
    onChange(next);
    setValue('');
    setField('partNumber');
    setOpen(false);
  };

  return (
    <div className={styles.chipsRow}>
      {chips.map((chip) => (
        <span key={chip.key} className={styles.chip}>
          <span className={styles.chipLabel}>{chip.label}</span>
          {chip.value}
          <button
            type="button"
            className={styles.chipX}
            aria-label={`Quitar filtro ${chip.label}`}
            onClick={() => onChange(withoutChip(criteria, chip.key))}
          >
            ×
          </button>
        </span>
      ))}

      <button
        type="button"
        className={styles.chipAdd}
        aria-label="Filtro"
        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
      >
        <i className="ti ti-plus" aria-hidden="true" />
        Filtro
      </button>

      {open && (
        <form className={styles.inlineForm} onSubmit={handleAdd}>
          <select
            aria-label="Campo"
            className={styles.fieldSelect}
            value={field}
            onChange={(e) => {
              setField(e.target.value as ChipKey);
              setValue('');
            }}
          >
            {FIELD_OPTIONS.map((o) => (
              <option key={o.key} value={o.key}>
                {o.label}
              </option>
            ))}
          </select>

          {field === 'zone' ? (
            <select
              aria-label="Valor"
              className={styles.valueSelect}
              value={value}
              onChange={(e) => setValue(e.target.value)}
            >
              <option value="">Selecciona zona…</option>
              {ZONES.map((z) => (
                <option key={z} value={z}>
                  {ZONE_LABELS[z]}
                </option>
              ))}
            </select>
          ) : (
            <input
              aria-label="Valor"
              className={styles.valueInput}
              type={field === 'minQuantity' || field === 'maxLeadTimeDays' ? 'number' : 'text'}
              min={field === 'minQuantity' || field === 'maxLeadTimeDays' ? 0 : undefined}
              placeholder={
                field === 'partNumber'
                  ? 'p. ej. 6205-2RS'
                  : field === 'brand'
                    ? 'p. ej. SKF'
                    : field === 'minQuantity'
                      ? 'p. ej. 500'
                      : 'p. ej. 7'
              }
              value={value}
              onChange={(e) => setValue(e.target.value)}
            />
          )}

          <button type="submit" className={styles.addBtn}>
            Añadir
          </button>
        </form>
      )}
    </div>
  );
}

