/* Las superficies que el HTML aprobado pinta en `white` puro (tabla, th
   pegajoso) no tienen token exacto: --bw-warm-cream es el neutro claro más
   cercano del sistema. */
.table {
  width: 100%;
  border-collapse: collapse;
  min-width: 860px;
}

.table th {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--bw-input-placeholder);
  padding: 10px 10px;
  text-align: left;
  border-bottom: 1px solid var(--bw-cold-white);
  white-space: nowrap;
  position: sticky;
  top: 0;
  background: var(--bw-warm-cream);
  z-index: 1;
}

.table td {
  padding: 10px 10px;
  border-bottom: 1px solid var(--bw-divider-mist);
  vertical-align: middle;
}

.table tr:last-child td {
  border-bottom: none;
}

.thChk {
  width: 36px;
  padding: 10px 8px 10px 14px;
}

.tdChk {
  padding: 10px 8px 10px 14px;
}

.sortBtn {
  background: none;
  border: none;
  padding: 0;
  margin: 0;
  font: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
  color: inherit;
  cursor: pointer;
}

.sortable:hover .sortBtn {
  color: var(--bw-steel-mist);
}

.sortAsc,
.sortDesc {
  color: var(--bw-calibration-blue);
}

.sortable .sortBtn::after {
  content: ' ·';
  opacity: 0.3;
}

.sortAsc .sortBtn::after {
  content: ' ↑';
  opacity: 1;
}

.sortDesc .sortBtn::after {
  content: ' ↓';
  opacity: 1;
}

/* La spec §3 pinta la fila ya consultada con rgba(37,99,235,0.04); no existe
   un token con esa opacidad exacta. --bw-row-hover-tint (0.025) es el
   derivado del azul de calibración más cercano. */
.consulted td {
  background: var(--bw-row-hover-tint);
}

.table tbody tr:hover:not(.consulted) td {
  background: var(--bw-hover-surface);
}

.cellRef {
  font-family: var(--bw-font-mono);
  font-size: 12px;
  color: var(--bw-deep-steel);
  white-space: nowrap;
}

/* El HTML aprobado usa #2D3748 sobre #E2E8F0; el par más cercano del sistema
   es deep-steel sobre vera-user-text. */
.badgeMarca {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  padding: 2px 7px;
  border-radius: 3px;
  background: var(--bw-deep-steel);
  color: var(--bw-vera-user-text);
  font-weight: 500;
  letter-spacing: 0.03em;
  white-space: nowrap;
}

.cellQty {
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
}

.ok {
  color: var(--bw-signal-green);
}

.low {
  color: var(--bw-steel-mist);
}

.cellPlazo {
  font-size: 12px;
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.cellEmpresa {
  font-size: 13px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.badgePais {
  font-size: 11px;
  padding: 2px 7px;
  border-radius: 3px;
  background: var(--bw-cold-white);
  color: var(--bw-ink-steel);
  font-weight: 500;
  white-space: nowrap;
  border: 1px solid var(--bw-line-steel);
}

.cellAntiguedad {
  font-size: 11px;
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.stale {
  color: var(--bw-warning);
  font-weight: 500;
}

.cellFav {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  cursor: pointer;
  color: var(--bw-brass);
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
  background: none;
  border: none;
  padding: 0;
  transition: opacity 0.12s;
  font-family: inherit;
}

.cellFav:hover {
  opacity: 0.7;
}

/* El HTML aprobado cambia la estrella a ámbar cuando el favorito está
   marcado; `aria-pressed` sostiene ese estado para lectores de pantalla. */
.cellFav[aria-pressed='true'] .favStar {
  color: var(--bw-warning);
}

.favStar {
  font-size: 14px;
}

.actionsCell {
  display: flex;
  gap: 5px;
  align-items: center;
}

.btnConsultar {
  height: 28px;
  padding: 0 11px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 4px;
  color: var(--bw-warm-cream);
  font-size: 11px;
  font-weight: 500;
  cursor: not-allowed;
  transition: opacity 0.12s;
  white-space: nowrap;
  font-family: inherit;
  opacity: 0.32;
}

.btnContactar {
  height: 28px;
  padding: 0 11px;
  background: transparent;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  color: var(--bw-ink-steel);
  font-size: 11px;
  font-weight: 500;
  cursor: not-allowed;
  transition: all 0.12s;
  white-space: nowrap;
  font-family: inherit;
  opacity: 0.55;
}

.checkbox {
  width: 15px;
  height: 15px;
  accent-color: var(--bw-calibration-blue);
  cursor: pointer;
}

.table td.emptyCell {
  text-align: center;
  padding: 48px 16px;
  color: var(--bw-steel-mist);
  font-size: 13px;
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

