import type { ReactNode } from 'react';
import {
  ageLabel,
  countryName,
  daysSince,
  leadTimeLabel,
  meetsMinQuantity,
  quantityLabel,
  type SearchResultRow,
  type Sort,
  type SortColumn,
} from '../../lib/search';
import styles from './ResultsTable.module.css';

function SortHeader({
  column,
  sort,
  onSort,
  children,
}: {
  column: SortColumn;
  sort: Sort | null;
  onSort: (column: SortColumn) => void;
  children: ReactNode;
}) {
  const active = sort !== null && sort.column === column;
  const cls = active ? (sort.direction === 'asc' ? styles.sortAsc : styles.sortDesc) : styles.sortable;
  return (
    <th
      className={cls}
      aria-sort={active ? (sort.direction === 'asc' ? 'ascending' : 'descending') : undefined}
    >
      {/* El botón dentro del th es el patrón WAI-ARIA de ordenación de tablas. */}
      <button type="button" className={styles.sortBtn} onClick={() => onSort(column)}>
        {children}
      </button>
    </th>
  );
}

/**
 * Tabla de resultados de SRCH-01.
 *
 * Presentacional: pinta las filas en el orden exacto en que las recibe
 * (ordenar es de la pantalla) y no carga datos. El estado vacío de la spec §6
 * vive aquí, dentro de la propia `<table>`, en su fila con `colSpan`.
 */
export function ResultsTable({
  rows,
  sort,
  selected,
  minQuantity,
  now,
  onSort,
  onToggleRow,
  onToggleFavorite,
  onConsult,
  onContact,
}: {
  rows: SearchResultRow[];
  sort: Sort | null;
  selected: ReadonlySet<string>;
  minQuantity: number | null;
  now?: Date;
  onSort: (column: SortColumn) => void;
  onToggleRow: (lineId: string) => void;
  onToggleFavorite: (orgId: string) => void;
  onConsult: (lineId: string) => void;
  onContact: (orgId: string) => void;
}) {
  return (
    <table className={styles.table}>
      <thead>
        <tr>
          <th className={styles.thChk}>
            <span className={styles.srOnly}>Seleccionar</span>
          </th>
          <th>Referencia</th>
          <SortHeader column="brand" sort={sort} onSort={onSort}>
            Marca
          </SortHeader>
          <SortHeader column="quantity" sort={sort} onSort={onSort}>
            Cantidad
          </SortHeader>
          <SortHeader column="leadTime" sort={sort} onSort={onSort}>
            Plazo
          </SortHeader>
          <th>Empresa</th>
          <SortHeader column="country" sort={sort} onSort={onSort}>
            País
          </SortHeader>
          <SortHeader column="age" sort={sort} onSort={onSort}>
            Antigüedad
          </SortHeader>
          <SortHeader column="favorites" sort={sort} onSort={onSort}>
            Favoritos
          </SortHeader>
          <th>
            <span className={styles.srOnly}>Acciones</span>
          </th>
        </tr>
      </thead>
      <tbody>
        {rows.length === 0 ? (
          <tr>
            <td colSpan={10} className={styles.emptyCell}>
              No hemos encontrado stock con estos filtros.
            </td>
          </tr>
        ) : (
          rows.map((row) => {
            const days = daysSince(row.lastUploadAt, now);
            const consultReason = row.consulted
              ? 'Ya consultada anteriormente. Usa «Consultar seleccionados».'
              : 'Consulta individual no disponible. Usa «Consultar seleccionados».';
            const contactReason = 'Contactar está fuera del alcance del MVP.';
            return (
              <tr key={row.id} className={row.consulted ? styles.consulted : undefined}>
                <td className={styles.tdChk}>
                  <input
                    type="checkbox"
                    className={styles.checkbox}
                    checked={selected.has(row.id)}
                    onChange={() => onToggleRow(row.id)}
                    aria-label={`Seleccionar ${row.partNumber}`}
                  />
                </td>
                <td>
                  <span className={styles.cellRef}>{row.partNumber}</span>
                </td>
                <td>
                  <span className={styles.badgeMarca}>{row.brand}</span>
                </td>
                <td>
                  <span
                    className={`${styles.cellQty} ${
                      meetsMinQuantity(row.quantity, minQuantity) ? styles.ok : styles.low
                    }`}
                  >
                    {quantityLabel(row.quantity)}
                  </span>
                </td>
                <td>
                  <span className={styles.cellPlazo}>{leadTimeLabel(row.leadTimeDays)}</span>
                </td>
                <td>
                  <span className={styles.cellEmpresa}>{row.orgName}</span>
                </td>
                <td>
                  <span className={styles.badgePais}>{countryName(row.country)}</span>
                </td>
                <td>
                  <span className={`${styles.cellAntiguedad} ${days > 7 ? styles.stale : ''}`}>
                    {ageLabel(days)}
                  </span>
                </td>
                <td>
                  <button
                    type="button"
                    className={styles.cellFav}
                    aria-pressed={row.isFavorite}
                    aria-label={`Favorito ${row.orgName}`}
                    onClick={() => onToggleFavorite(row.orgId)}
                  >
                    <span className={styles.favStar} aria-hidden="true">
                      ★
                    </span>
                    <span>{row.favoriteCount}</span>
                  </button>
                </td>
                <td>
                  <div className={styles.actionsCell}>
                    <button
                      type="button"
                      className={styles.btnConsultar}
                      disabled
                      title={consultReason}
                      onClick={() => onConsult(row.id)}
                    >
                      Consultar
                    </button>
                    <button
                      type="button"
                      className={styles.btnContactar}
                      disabled
                      title={contactReason}
                      onClick={() => onContact(row.orgId)}
                    >
                      Contactar
                    </button>
                  </div>
                </td>
              </tr>
            );
          })
        )}
      </tbody>
    </table>
  );
}

