import { useEffect, useMemo, useRef, useState } from 'react';
import { sendInquiries } from '../../lib/thread-detail';
import type { MemberProfile } from '../../lib/session';
import {
  EMPTY_CRITERIA,
  consultSummary,
  fetchResults,
  metaCounterLabel,
  meetsMinQuantity,
  nextSort,
  sortRows,
  toggleFavorite,
  type SearchCriteria,
  type SearchPage,
  type Sort,
  type SortColumn,
} from '../../lib/search';
import { FilterChips } from './FilterChips';
import { ResultsTable } from './ResultsTable';
import styles from './SearchResults.module.css';

/**
 * SRCH-01 · Panel de Resultados de Búsqueda.
 *
 * Es la pantalla, no un componente de presentación: posee criterios, orden,
 * selección, carga, error y el aviso de resultado de las consultas en lote;
 * ordena las filas con `sortRows` y delega en FilterChips y ResultsTable, que
 * son presentacionales y reciben todo por props.
 */
export function SearchResults({
  profile,
  now,
  veraCriteria,
}: {
  profile: MemberProfile;
  now?: Date;
  veraCriteria?: SearchCriteria | null;
}) {
  // F-118 · Congelación del corpus (28-ago-2026). El shell la cablea desde
  // App.tsx y es la firma pública del componente, pero el cableado
  // VERA <-> chips es la fila del día 9 del Plan §3 y sigue en out_of_scope.
  // Se recibe y se ignora.
  void veraCriteria;

  const [criteria, setCriteria] = useState<SearchCriteria>(EMPTY_CRITERIA);
  const [sort, setSort] = useState<Sort | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [page, setPage] = useState<SearchPage | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const [reloadKey, setReloadKey] = useState(0);
  const [consultNotice, setConsultNotice] = useState<string | null>(null);
  const [sending, setSending] = useState(false);
  const sendingRef = useRef(false);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(false);
    fetchResults({ orgId: profile.orgId, memberId: profile.id, criteria })
      .then((p) => {
        if (cancelled) return;
        setPage(p);
        setSelected(new Set());
        setLoading(false);
      })
      .catch(() => {
        if (cancelled) return;
        setPage(null);
        setError(true);
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [profile.orgId, profile.id, criteria, reloadKey]);

  const sortedRows = useMemo(() => (page ? sortRows(page.rows, sort) : []), [page, sort]);

  const withStock = useMemo(
    () => (page ? page.rows.filter((r) => meetsMinQuantity(r.quantity, criteria.minQuantity)).length : 0),
    [page, criteria.minQuantity],
  );

  const metaLabel = page ? metaCounterLabel(page.total, withStock, criteria.minQuantity) : '';

  const allSelected = page !== null && page.rows.length > 0 && page.rows.every((r) => selected.has(r.id));

  const handleCriteriaChange = (next: SearchCriteria) => {
    setCriteria(next);
    setSelected(new Set());
    setConsultNotice(null);
  };

  const handleSort = (column: SortColumn) => {
    setSort(nextSort(sort, column));
  };

  const toggleRow = (lineId: string) => {
    setSelected((prev) => {
      const nextSet = new Set(prev);
      if (nextSet.has(lineId)) nextSet.delete(lineId);
      else nextSet.add(lineId);
      return nextSet;
    });
  };

  const toggleSelectAll = () => {
    if (!page) return;
    setSelected(allSelected ? new Set() : new Set(page.rows.map((r) => r.id)));
  };

  const handleToggleFavorite = async (orgId: string) => {
    if (!page) return;
    const row = page.rows.find((r) => r.orgId === orgId);
    if (!row) return;
    try {
      await toggleFavorite(profile.id, orgId, !row.isFavorite);
      setReloadKey((k) => k + 1);
    } catch {
      // El recuento se relee de la base; si la escritura falla, la pantalla
      // simplemente conserva el estado que ya mostraba.
    }
  };

  const consultSelected = async () => {
    if (!page || sendingRef.current) return;
    const selectedRows = page.rows.filter((r) => selected.has(r.id));
    // La capability manda: el lote necesita al menos dos filas. Con una sola,
    // la acción correcta es la Consultar individual de la fila.
    if (selectedRows.length < 2) return;

    const pending = selectedRows.filter((r) => !r.consulted);
    const omitidas = selectedRows.length - pending.length;

    sendingRef.current = true;
    setSending(true);
    try {
      const resultados =
        pending.length > 0
          ? await sendInquiries(
              pending.map((r) => ({
                lineId: r.id,
                distributorOrgId: r.orgId,
                quantity: r.quantity,
              })),
              profile.orgId,
            )
          : [];
      setConsultNotice(consultSummary(resultados, omitidas));
      setSelected(new Set());
      // El usuario permanece en SRCH-01: se relee la tabla para que el estado
      // «ya consultada» salga de la base y no de un retoque en cliente.
      setReloadKey((k) => k + 1);
    } catch {
      setConsultNotice('No se pudieron enviar las consultas. Inténtalo de nuevo.');
    } finally {
      sendingRef.current = false;
      setSending(false);
    }
  };

  return (
    <div className={styles.page}>
      <div className={styles.eyebrow}>Módulo 03 · Búsqueda Conversacional</div>
      <h1 className={styles.title}>Resultados de búsqueda</h1>

      <FilterChips criteria={criteria} onChange={handleCriteriaChange} />

      <div className={styles.metabar}>
        {page !== null && !loading && <div className={styles.metaCount}>{metaLabel}</div>}
        {page !== null && !loading && page.rows.length > 0 && (
          <button type="button" className={styles.btnSelAll} onClick={toggleSelectAll}>
            {allSelected ? 'Deseleccionar todos' : 'Seleccionar todos'}
          </button>
        )}
        <button
          type="button"
          className={styles.btnConsultarSel}
          disabled={selected.size < 2 || sending}
          onClick={consultSelected}
        >
          Consultar seleccionados
        </button>
        <button
          type="button"
          className={styles.btnWatcher}
          disabled
          title="Crear watchers con estos criterios (SRCH-03) está fuera del alcance del MVP."
        >
          <i className="ti ti-bell-plus" aria-hidden="true" />
          Crear watcher con estos criterios
        </button>
      </div>

      <div className={styles.resultsArea} aria-busy={loading}>
        {page !== null && page.capped && !loading && (
          <div className={styles.cappedWarning} role="status">
            Mostrando los primeros 200 resultados. Afina los filtros para verlos todos.
          </div>
        )}

        {consultNotice !== null && (
          <div className={styles.consultNotice} role="status">
            {consultNotice}
          </div>
        )}

        {loading ? (
          <div className={styles.loadingBox} role="status">
            <div className={styles.spinner} aria-hidden="true" />
            <span className={styles.srOnly}>Buscando...</span>
          </div>
        ) : error ? (
          <div className={styles.errorBox} role="alert">
            <p className={styles.errorText}>No se pudieron cargar los resultados. Inténtalo de nuevo.</p>
            <button type="button" className={styles.retryBtn} onClick={() => setReloadKey((k) => k + 1)}>
              Reintentar
            </button>
          </div>
        ) : (
          <div className={styles.tableOuter}>
            <ResultsTable
              rows={sortedRows}
              sort={sort}
              selected={selected}
              minQuantity={criteria.minQuantity}
              {...(now !== undefined ? { now } : {})}
              onSort={handleSort}
              onToggleRow={toggleRow}
              onToggleFavorite={handleToggleFavorite}
              onConsult={() => {}}
              onContact={() => {}}
            />
          </div>
        )}
      </div>
    </div>
  );
}
